___CSS_LOADER_EXPORT___.push([module.id, `/* TaskFlow Design System - Vanilla CSS with tf- prefix */
:root {
  /* Primary Colors & Accents */
  --tf-teal-base: #14b8a6;
  --tf-teal-hover: #0d9488;
  --tf-teal-light: #f0fdfa;
  --tf-teal-subtle: #ccf0ee;

  /* Backgrounds */
  --tf-bg-main-start: #f4f7f9;
  --tf-bg-main-end: #e8f0f2;
  --tf-bg-sidebar: #0f172a;
  --tf-bg-card: #ffffff;
  --tf-bg-column-start: #f8fafc;
  --tf-bg-column-end: #f1f5f9;

  /* Text Colors */
  --tf-text-dark: #0f172a;
  --tf-text-muted: #64748b;
  --tf-text-light: #94a3b8;

  /* Shadows */
  --tf-shadow-sm: 0 2px 5px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);
  --tf-shadow-hover: 0 12px 24px -4px rgba(20, 184, 166, 0.15);
  --tf-shadow-lg: 0 20px 40px -4px rgba(20, 184, 166, 0.2);

  /* Border Radius */
  --tf-radius-card: 12px;
  --tf-radius-pill: 9999px;

  /* Spacing */
  --tf-gap-sm: 8px;
  --tf-gap-md: 12px;
  --tf-gap-lg: 16px;

  /* Transitions */
  --tf-transition: all 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Main Board Grid */
.tf-board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
  padding: 0;
  background: transparent;
  border-radius: 0;
  min-height: 75%;
  width: 100%;
}

/* Column Container */
.tf-column {
  display: flex;
  flex-direction: column;
  background: #f6f9fc;
  border-radius: var(--tf-radius-card);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.02);
  overflow: hidden;
  min-height: 300px;
  transition: var(--tf-transition);
}

/* Column Hover State (when dragging over) */
.tf-column.tf-column--drag-over {
  background: linear-gradient(180deg, var(--tf-teal-light) 0%, #f0fdfa 100%);
  border-color: var(--tf-teal-base);
  box-shadow: 0 8px 16px -2px rgba(20, 184, 166, 0.12);
}

/* Column Header */
.tf-column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
  border-bottom: 1px dashed #e2e8f0;
  background: #f6f9fc;
}

/* Column Title Wrapper */
.tf-column-title-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

/* Column Title */
.tf-column-title {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--tf-text-dark);
  font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* Column Count Badge */
.tf-column-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--tf-teal-base);
  background: transparent;
  border: none;
}

/* Add Task Button */
.tf-column-add-btn {
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--tf-radius-pill);
  background: transparent;
  color: #64748b;
  font-size: 1.65rem;
  font-weight: 400;
  line-height: 1;
  cursor: pointer;
  transition: color 200ms cubic-bezier(0.4, 0, 0.2, 1);
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.tf-column-add-btn:hover {
  color: #14b8a6;
}

.tf-column-add-btn:active {
  transform: scale(0.95);
}

/* Tasks List Container */
.tf-tasks-list {
  flex: 1 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  overflow-y: auto;
  scroll-behavior: smooth;
}

/* Empty State */
.tf-empty-message {
  margin: 0;
  padding: 20px 12px;
  text-align: center;
  color: var(--tf-text-light);
  font-size: 0.875rem;
  flex-grow: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Task Card */
.tf-task-card {
  background: var(--tf-bg-card);
  border: 1px solid #e2e8f0;
  border-radius: var(--tf-radius-card);
  padding: 12px;
  box-shadow: var(--tf-shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 0;
  transition: var(--tf-transition);
  position: relative;
  cursor: pointer;
}

.tf-task-card:not(.tf-task-card--locked):hover {
  transform: translateY(-4px);
  border-color: #8fd9d2;
  box-shadow: none;
}

.tf-task-card:active {
  cursor: grabbing;
}

.tf-task-card--locked {
  cursor: grab;
}

/* Dragging State */
.tf-task-card--dragging {
  opacity: 0.5;
  transform: rotate(3deg) scale(0.95);
}

.tf-task-card--drag-image {
  opacity: 1 !important;
  filter: none !important;
}

/* Task Card Inner */
.tf-task-card-inner {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Task Card Top Line (Priority) */
.tf-task-card-topline {
  min-height: 18px;
}

/* Priority Line */
.tf-priority-line {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.7rem;
  line-height: 1;
  color: var(--tf-text-muted);
}

/* Priority Prefix */
.tf-priority-prefix {
  color: #94a3b8;
  font-weight: 600;
}

/* Priority Pill Badge */
.tf-priority-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  border-radius: var(--tf-radius-pill);
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  background: #f3f4f6;
  color: #6b7280;
}

.tf-priority-high {
  background: #fee2e2;
  color: #991b1b;
}

.tf-priority-medium {
  background: #fef3c7;
  color: #92400e;
}

.tf-priority-low {
  background: #d1fae5;
  color: #065f46;
}

.tf-priority-urgent {
  background: #fecaca;
  color: #7f1d1d;
}

.tf-priority-unset {
  background: #e5e7eb;
  color: #6b7280;
}

/* Task Title */
.tf-task-title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.3;
  color: var(--tf-text-dark);
  word-wrap: break-word;
}

/* Task Pending */
.tf-task-pending {
  margin: 0;
  font-size: 0.75rem;
  color: var(--tf-teal-base);
  font-weight: 600;
}

/* Task Description */
.tf-task-desc {
  margin: 0;
  color: var(--tf-text-muted);
  font-size: 0.8rem;
  line-height: 1.45;
}

/* Task Meta Info */
.tf-task-meta {
  margin: 0;
  font-size: 0.75rem;
  color: var(--tf-text-muted);
  line-height: 1.4;
}

.tf-task-meta-name {
  font-weight: 700;
  color: var(--tf-text-dark);
}

/* Overdue Badge */
.is-overdue {
  color: #dc2626 !important;
  font-weight: 700;
}

.tdm-overdue-badge {
  display: inline-block;
  padding: 2px 6px;
  background: #fee2e2;
  color: #991b1b;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: var(--tf-radius-pill);
}

/* Task Divider */
.tf-task-divider {
  height: 1px;
  background: #e5e7eb;
  margin: 8px 0;
}

/* Task Footer Row */
.tf-task-footer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
}

/* Task Assignee Block */
.tf-task-assignee-block {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1 1;
}

/* Task Assignee Label */
.tf-task-assignee-label {
  color: var(--tf-text-muted);
  font-weight: 600;
  font-size: 0.75rem;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Task Avatar Row */
.tf-task-avatar-row {
  display: flex;
  align-items: center;
  gap: 0;
  flex-wrap: nowrap;
  padding-left: 0;
  min-width: 0;
}

/* Task Avatar */
.tf-task-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--tf-radius-pill);
  border: 2px solid #ffffff;
  background: linear-gradient(135deg, var(--tf-teal-light) 0%, #d1fae5 100%);
  color: var(--tf-teal-base);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  box-shadow: var(--tf-shadow-sm);
  flex-shrink: 0;
  overflow: hidden;
}

.tf-task-avatar img {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: var(--tf-radius-pill);
  object-fit: cover;
}

/* Overlapping Avatar Effect */
.tf-task-avatar + .tf-task-avatar {
  margin-left: -10px;
}

.tf-task-avatar:nth-child(1) {
  z-index: 3;
}

.tf-task-avatar:nth-child(2) {
  z-index: 2;
}

.tf-task-avatar:nth-child(3) {
  z-index: 1;
}

/* Unassigned */
.tf-task-unassigned {
  color: var(--tf-text-muted);
  font-size: 0.75rem;
  font-weight: 500;
}

/* Task Action Button */
.tf-task-action {
  width: fit-content;
  padding: 6px 12px;
  border: 1px solid #cbd5e1;
  border-radius: var(--tf-radius-pill);
  background: var(--tf-bg-card);
  color: var(--tf-text-dark);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: var(--tf-transition);
  box-shadow: var(--tf-shadow-sm);
  flex-shrink: 0;
  white-space: nowrap;
}

.tf-task-action:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #94a3b8;
}

.tf-task-action--take {
  color: var(--tf-teal-base);
  border-color: var(--tf-teal-subtle);
  background: var(--tf-teal-light);
}

.tf-task-action--take:hover:not(:disabled) {
  background: var(--tf-teal-subtle);
  border-color: var(--tf-teal-base);
  color: var(--tf-teal-hover);
}

.tf-task-action--unassign {
  border-color: #cbd5e1;
  background: var(--tf-bg-card);
  color: var(--tf-text-dark);
}

.tf-task-action--unassign:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #94a3b8;
}

.tf-task-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Task Helper Text */
.tf-task-helper {
  margin: 0;
  color: var(--tf-text-light);
  font-size: 0.7rem;
  line-height: 1.3;
}

/* Responsive */
@media (max-width: 1024px) {
  .tf-board {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 12px;
    padding: 12px;
  }
}

@media (max-width: 768px) {
  .tf-board {
    grid-template-columns: 1fr;
  }

  .tf-column {
    min-height: 300px;
  }

  .tf-task-footer-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .tf-task-assignee-block {
    width: 100%;
  }

  .tf-task-action {
    width: 100%;
    justify-content: center;
  }
}

`, "",{"version":3,"sources":["webpack://./src/components/styles/KanbanBoard.css"],"names":[],"mappings":"AAAA,yDAAyD;AACzD;EACE,6BAA6B;EAC7B,uBAAuB;EACvB,wBAAwB;EACxB,wBAAwB;EACxB,yBAAyB;;EAEzB,gBAAgB;EAChB,2BAA2B;EAC3B,yBAAyB;EACzB,wBAAwB;EACxB,qBAAqB;EACrB,6BAA6B;EAC7B,2BAA2B;;EAE3B,gBAAgB;EAChB,uBAAuB;EACvB,wBAAwB;EACxB,wBAAwB;;EAExB,YAAY;EACZ,4EAA4E;EAC5E,4DAA4D;EAC5D,wDAAwD;;EAExD,kBAAkB;EAClB,sBAAsB;EACtB,wBAAwB;;EAExB,YAAY;EACZ,gBAAgB;EAChB,iBAAiB;EACjB,iBAAiB;;EAEjB,gBAAgB;EAChB,uDAAuD;AACzD;;AAEA,oBAAoB;AACpB;EACE,aAAa;EACb,2DAA2D;EAC3D,SAAS;EACT,UAAU;EACV,uBAAuB;EACvB,gBAAgB;EAChB,eAAe;EACf,WAAW;AACb;;AAEA,qBAAqB;AACrB;EACE,aAAa;EACb,sBAAsB;EACtB,mBAAmB;EACnB,oCAAoC;EACpC,wEAAwE;EACxE,gBAAgB;EAChB,iBAAiB;EACjB,gCAAgC;AAClC;;AAEA,4CAA4C;AAC5C;EACE,0EAA0E;EAC1E,iCAAiC;EACjC,oDAAoD;AACtD;;AAEA,kBAAkB;AAClB;EACE,aAAa;EACb,mBAAmB;EACnB,8BAA8B;EAC9B,aAAa;EACb,iCAAiC;EACjC,mBAAmB;AACrB;;AAEA,yBAAyB;AACzB;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,YAAY;AACd;;AAEA,iBAAiB;AACjB;EACE,SAAS;EACT,mBAAmB;EACnB,gBAAgB;EAChB,sBAAsB;EACtB,yBAAyB;EACzB,0BAA0B;EAC1B,6EAA6E;AAC/E;;AAEA,uBAAuB;AACvB;EACE,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;EACvB,kBAAkB;EAClB,gBAAgB;EAChB,0BAA0B;EAC1B,uBAAuB;EACvB,YAAY;AACd;;AAEA,oBAAoB;AACpB;EACE,WAAW;EACX,YAAY;EACZ,UAAU;EACV,YAAY;EACZ,oCAAoC;EACpC,uBAAuB;EACvB,cAAc;EACd,kBAAkB;EAClB,gBAAgB;EAChB,cAAc;EACd,eAAe;EACf,oDAAoD;EACpD,cAAc;EACd,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;AACzB;;AAEA;EACE,cAAc;AAChB;;AAEA;EACE,sBAAsB;AACxB;;AAEA,yBAAyB;AACzB;EACE,SAAO;EACP,aAAa;EACb,sBAAsB;EACtB,SAAS;EACT,aAAa;EACb,gBAAgB;EAChB,uBAAuB;AACzB;;AAEA,gBAAgB;AAChB;EACE,SAAS;EACT,kBAAkB;EAClB,kBAAkB;EAClB,2BAA2B;EAC3B,mBAAmB;EACnB,YAAY;EACZ,aAAa;EACb,mBAAmB;EACnB,uBAAuB;AACzB;;AAEA,cAAc;AACd;EACE,6BAA6B;EAC7B,yBAAyB;EACzB,oCAAoC;EACpC,aAAa;EACb,+BAA+B;EAC/B,aAAa;EACb,sBAAsB;EACtB,MAAM;EACN,gCAAgC;EAChC,kBAAkB;EAClB,eAAe;AACjB;;AAEA;EACE,2BAA2B;EAC3B,qBAAqB;EACrB,gBAAgB;AAClB;;AAEA;EACE,gBAAgB;AAClB;;AAEA;EACE,YAAY;AACd;;AAEA,mBAAmB;AACnB;EACE,YAAY;EACZ,mCAAmC;AACrC;;AAEA;EACE,qBAAqB;EACrB,uBAAuB;AACzB;;AAEA,oBAAoB;AACpB;EACE,aAAa;EACb,sBAAsB;EACtB,QAAQ;AACV;;AAEA,kCAAkC;AAClC;EACE,gBAAgB;AAClB;;AAEA,kBAAkB;AAClB;EACE,oBAAoB;EACpB,mBAAmB;EACnB,QAAQ;EACR,iBAAiB;EACjB,cAAc;EACd,2BAA2B;AAC7B;;AAEA,oBAAoB;AACpB;EACE,cAAc;EACd,gBAAgB;AAClB;;AAEA,wBAAwB;AACxB;EACE,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;EACvB,gBAAgB;EAChB,oCAAoC;EACpC,kBAAkB;EAClB,gBAAgB;EAChB,yBAAyB;EACzB,sBAAsB;EACtB,mBAAmB;EACnB,cAAc;AAChB;;AAEA;EACE,mBAAmB;EACnB,cAAc;AAChB;;AAEA;EACE,mBAAmB;EACnB,cAAc;AAChB;;AAEA;EACE,mBAAmB;EACnB,cAAc;AAChB;;AAEA;EACE,mBAAmB;EACnB,cAAc;AAChB;;AAEA;EACE,mBAAmB;EACnB,cAAc;AAChB;;AAEA,eAAe;AACf;EACE,SAAS;EACT,kBAAkB;EAClB,gBAAgB;EAChB,gBAAgB;EAChB,0BAA0B;EAC1B,qBAAqB;AACvB;;AAEA,iBAAiB;AACjB;EACE,SAAS;EACT,kBAAkB;EAClB,0BAA0B;EAC1B,gBAAgB;AAClB;;AAEA,qBAAqB;AACrB;EACE,SAAS;EACT,2BAA2B;EAC3B,iBAAiB;EACjB,iBAAiB;AACnB;;AAEA,mBAAmB;AACnB;EACE,SAAS;EACT,kBAAkB;EAClB,2BAA2B;EAC3B,gBAAgB;AAClB;;AAEA;EACE,gBAAgB;EAChB,0BAA0B;AAC5B;;AAEA,kBAAkB;AAClB;EACE,yBAAyB;EACzB,gBAAgB;AAClB;;AAEA;EACE,qBAAqB;EACrB,gBAAgB;EAChB,mBAAmB;EACnB,cAAc;EACd,kBAAkB;EAClB,gBAAgB;EAChB,oCAAoC;AACtC;;AAEA,iBAAiB;AACjB;EACE,WAAW;EACX,mBAAmB;EACnB,aAAa;AACf;;AAEA,oBAAoB;AACpB;EACE,aAAa;EACb,mBAAmB;EACnB,8BAA8B;EAC9B,SAAS;EACT,eAAe;AACjB;;AAEA,wBAAwB;AACxB;EACE,aAAa;EACb,mBAAmB;EACnB,QAAQ;EACR,YAAY;EACZ,SAAO;AACT;;AAEA,wBAAwB;AACxB;EACE,2BAA2B;EAC3B,gBAAgB;EAChB,kBAAkB;EAClB,mBAAmB;EACnB,cAAc;AAChB;;AAEA,oBAAoB;AACpB;EACE,aAAa;EACb,mBAAmB;EACnB,MAAM;EACN,iBAAiB;EACjB,eAAe;EACf,YAAY;AACd;;AAEA,gBAAgB;AAChB;EACE,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;EACvB,WAAW;EACX,YAAY;EACZ,oCAAoC;EACpC,yBAAyB;EACzB,0EAA0E;EAC1E,0BAA0B;EAC1B,kBAAkB;EAClB,gBAAgB;EAChB,sBAAsB;EACtB,+BAA+B;EAC/B,cAAc;EACd,gBAAgB;AAClB;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,cAAc;EACd,oCAAoC;EACpC,iBAAiB;AACnB;;AAEA,8BAA8B;AAC9B;EACE,kBAAkB;AACpB;;AAEA;EACE,UAAU;AACZ;;AAEA;EACE,UAAU;AACZ;;AAEA;EACE,UAAU;AACZ;;AAEA,eAAe;AACf;EACE,2BAA2B;EAC3B,kBAAkB;EAClB,gBAAgB;AAClB;;AAEA,uBAAuB;AACvB;EACE,kBAAkB;EAClB,iBAAiB;EACjB,yBAAyB;EACzB,oCAAoC;EACpC,6BAA6B;EAC7B,0BAA0B;EAC1B,iBAAiB;EACjB,gBAAgB;EAChB,yBAAyB;EACzB,sBAAsB;EACtB,eAAe;EACf,gCAAgC;EAChC,+BAA+B;EAC/B,cAAc;EACd,mBAAmB;AACrB;;AAEA;EACE,mBAAmB;EACnB,qBAAqB;AACvB;;AAEA;EACE,0BAA0B;EAC1B,mCAAmC;EACnC,gCAAgC;AAClC;;AAEA;EACE,iCAAiC;EACjC,iCAAiC;EACjC,2BAA2B;AAC7B;;AAEA;EACE,qBAAqB;EACrB,6BAA6B;EAC7B,0BAA0B;AAC5B;;AAEA;EACE,mBAAmB;EACnB,qBAAqB;AACvB;;AAEA;EACE,YAAY;EACZ,mBAAmB;AACrB;;AAEA,qBAAqB;AACrB;EACE,SAAS;EACT,2BAA2B;EAC3B,iBAAiB;EACjB,gBAAgB;AAClB;;AAEA,eAAe;AACf;EACE;IACE,2DAA2D;IAC3D,SAAS;IACT,aAAa;EACf;AACF;;AAEA;EACE;IACE,0BAA0B;EAC5B;;EAEA;IACE,iBAAiB;EACnB;;EAEA;IACE,sBAAsB;IACtB,uBAAuB;EACzB;;EAEA;IACE,WAAW;EACb;;EAEA;IACE,WAAW;IACX,uBAAuB;EACzB;AACF","sourcesContent":["/* TaskFlow Design System - Vanilla CSS with tf- prefix */\r\n:root {\r\n  /* Primary Colors & Accents */\r\n  --tf-teal-base: #14b8a6;\r\n  --tf-teal-hover: #0d9488;\r\n  --tf-teal-light: #f0fdfa;\r\n  --tf-teal-subtle: #ccf0ee;\r\n\r\n  /* Backgrounds */\r\n  --tf-bg-main-start: #f4f7f9;\r\n  --tf-bg-main-end: #e8f0f2;\r\n  --tf-bg-sidebar: #0f172a;\r\n  --tf-bg-card: #ffffff;\r\n  --tf-bg-column-start: #f8fafc;\r\n  --tf-bg-column-end: #f1f5f9;\r\n\r\n  /* Text Colors */\r\n  --tf-text-dark: #0f172a;\r\n  --tf-text-muted: #64748b;\r\n  --tf-text-light: #94a3b8;\r\n\r\n  /* Shadows */\r\n  --tf-shadow-sm: 0 2px 5px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);\r\n  --tf-shadow-hover: 0 12px 24px -4px rgba(20, 184, 166, 0.15);\r\n  --tf-shadow-lg: 0 20px 40px -4px rgba(20, 184, 166, 0.2);\r\n\r\n  /* Border Radius */\r\n  --tf-radius-card: 12px;\r\n  --tf-radius-pill: 9999px;\r\n\r\n  /* Spacing */\r\n  --tf-gap-sm: 8px;\r\n  --tf-gap-md: 12px;\r\n  --tf-gap-lg: 16px;\r\n\r\n  /* Transitions */\r\n  --tf-transition: all 200ms cubic-bezier(0.4, 0, 0.2, 1);\r\n}\r\n\r\n/* Main Board Grid */\r\n.tf-board {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\r\n  gap: 16px;\r\n  padding: 0;\r\n  background: transparent;\r\n  border-radius: 0;\r\n  min-height: 75%;\r\n  width: 100%;\r\n}\r\n\r\n/* Column Container */\r\n.tf-column {\r\n  display: flex;\r\n  flex-direction: column;\r\n  background: #f6f9fc;\r\n  border-radius: var(--tf-radius-card);\r\n  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.02);\r\n  overflow: hidden;\r\n  min-height: 300px;\r\n  transition: var(--tf-transition);\r\n}\r\n\r\n/* Column Hover State (when dragging over) */\r\n.tf-column.tf-column--drag-over {\r\n  background: linear-gradient(180deg, var(--tf-teal-light) 0%, #f0fdfa 100%);\r\n  border-color: var(--tf-teal-base);\r\n  box-shadow: 0 8px 16px -2px rgba(20, 184, 166, 0.12);\r\n}\r\n\r\n/* Column Header */\r\n.tf-column-header {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 12px;\r\n  border-bottom: 1px dashed #e2e8f0;\r\n  background: #f6f9fc;\r\n}\r\n\r\n/* Column Title Wrapper */\r\n.tf-column-title-wrap {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  min-width: 0;\r\n}\r\n\r\n/* Column Title */\r\n.tf-column-title {\r\n  margin: 0;\r\n  font-size: 0.875rem;\r\n  font-weight: 700;\r\n  letter-spacing: 0.05em;\r\n  text-transform: uppercase;\r\n  color: var(--tf-text-dark);\r\n  font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\r\n}\r\n\r\n/* Column Count Badge */\r\n.tf-column-count {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 0.75rem;\r\n  font-weight: 700;\r\n  color: var(--tf-teal-base);\r\n  background: transparent;\r\n  border: none;\r\n}\r\n\r\n/* Add Task Button */\r\n.tf-column-add-btn {\r\n  width: 32px;\r\n  height: 32px;\r\n  padding: 0;\r\n  border: none;\r\n  border-radius: var(--tf-radius-pill);\r\n  background: transparent;\r\n  color: #64748b;\r\n  font-size: 1.65rem;\r\n  font-weight: 400;\r\n  line-height: 1;\r\n  cursor: pointer;\r\n  transition: color 200ms cubic-bezier(0.4, 0, 0.2, 1);\r\n  flex-shrink: 0;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.tf-column-add-btn:hover {\r\n  color: #14b8a6;\r\n}\r\n\r\n.tf-column-add-btn:active {\r\n  transform: scale(0.95);\r\n}\r\n\r\n/* Tasks List Container */\r\n.tf-tasks-list {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n  padding: 12px;\r\n  overflow-y: auto;\r\n  scroll-behavior: smooth;\r\n}\r\n\r\n/* Empty State */\r\n.tf-empty-message {\r\n  margin: 0;\r\n  padding: 20px 12px;\r\n  text-align: center;\r\n  color: var(--tf-text-light);\r\n  font-size: 0.875rem;\r\n  flex-grow: 1;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n/* Task Card */\r\n.tf-task-card {\r\n  background: var(--tf-bg-card);\r\n  border: 1px solid #e2e8f0;\r\n  border-radius: var(--tf-radius-card);\r\n  padding: 12px;\r\n  box-shadow: var(--tf-shadow-sm);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0;\r\n  transition: var(--tf-transition);\r\n  position: relative;\r\n  cursor: pointer;\r\n}\r\n\r\n.tf-task-card:not(.tf-task-card--locked):hover {\r\n  transform: translateY(-4px);\r\n  border-color: #8fd9d2;\r\n  box-shadow: none;\r\n}\r\n\r\n.tf-task-card:active {\r\n  cursor: grabbing;\r\n}\r\n\r\n.tf-task-card--locked {\r\n  cursor: grab;\r\n}\r\n\r\n/* Dragging State */\r\n.tf-task-card--dragging {\r\n  opacity: 0.5;\r\n  transform: rotate(3deg) scale(0.95);\r\n}\r\n\r\n.tf-task-card--drag-image {\r\n  opacity: 1 !important;\r\n  filter: none !important;\r\n}\r\n\r\n/* Task Card Inner */\r\n.tf-task-card-inner {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n/* Task Card Top Line (Priority) */\r\n.tf-task-card-topline {\r\n  min-height: 18px;\r\n}\r\n\r\n/* Priority Line */\r\n.tf-priority-line {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  font-size: 0.7rem;\r\n  line-height: 1;\r\n  color: var(--tf-text-muted);\r\n}\r\n\r\n/* Priority Prefix */\r\n.tf-priority-prefix {\r\n  color: #94a3b8;\r\n  font-weight: 600;\r\n}\r\n\r\n/* Priority Pill Badge */\r\n.tf-priority-pill {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 2px 8px;\r\n  border-radius: var(--tf-radius-pill);\r\n  font-size: 0.65rem;\r\n  font-weight: 700;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.02em;\r\n  background: #f3f4f6;\r\n  color: #6b7280;\r\n}\r\n\r\n.tf-priority-high {\r\n  background: #fee2e2;\r\n  color: #991b1b;\r\n}\r\n\r\n.tf-priority-medium {\r\n  background: #fef3c7;\r\n  color: #92400e;\r\n}\r\n\r\n.tf-priority-low {\r\n  background: #d1fae5;\r\n  color: #065f46;\r\n}\r\n\r\n.tf-priority-urgent {\r\n  background: #fecaca;\r\n  color: #7f1d1d;\r\n}\r\n\r\n.tf-priority-unset {\r\n  background: #e5e7eb;\r\n  color: #6b7280;\r\n}\r\n\r\n/* Task Title */\r\n.tf-task-title {\r\n  margin: 0;\r\n  font-size: 0.95rem;\r\n  font-weight: 800;\r\n  line-height: 1.3;\r\n  color: var(--tf-text-dark);\r\n  word-wrap: break-word;\r\n}\r\n\r\n/* Task Pending */\r\n.tf-task-pending {\r\n  margin: 0;\r\n  font-size: 0.75rem;\r\n  color: var(--tf-teal-base);\r\n  font-weight: 600;\r\n}\r\n\r\n/* Task Description */\r\n.tf-task-desc {\r\n  margin: 0;\r\n  color: var(--tf-text-muted);\r\n  font-size: 0.8rem;\r\n  line-height: 1.45;\r\n}\r\n\r\n/* Task Meta Info */\r\n.tf-task-meta {\r\n  margin: 0;\r\n  font-size: 0.75rem;\r\n  color: var(--tf-text-muted);\r\n  line-height: 1.4;\r\n}\r\n\r\n.tf-task-meta-name {\r\n  font-weight: 700;\r\n  color: var(--tf-text-dark);\r\n}\r\n\r\n/* Overdue Badge */\r\n.is-overdue {\r\n  color: #dc2626 !important;\r\n  font-weight: 700;\r\n}\r\n\r\n.tdm-overdue-badge {\r\n  display: inline-block;\r\n  padding: 2px 6px;\r\n  background: #fee2e2;\r\n  color: #991b1b;\r\n  font-size: 0.65rem;\r\n  font-weight: 700;\r\n  border-radius: var(--tf-radius-pill);\r\n}\r\n\r\n/* Task Divider */\r\n.tf-task-divider {\r\n  height: 1px;\r\n  background: #e5e7eb;\r\n  margin: 8px 0;\r\n}\r\n\r\n/* Task Footer Row */\r\n.tf-task-footer-row {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  margin-top: 4px;\r\n}\r\n\r\n/* Task Assignee Block */\r\n.tf-task-assignee-block {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  min-width: 0;\r\n  flex: 1;\r\n}\r\n\r\n/* Task Assignee Label */\r\n.tf-task-assignee-label {\r\n  color: var(--tf-text-muted);\r\n  font-weight: 600;\r\n  font-size: 0.75rem;\r\n  white-space: nowrap;\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* Task Avatar Row */\r\n.tf-task-avatar-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0;\r\n  flex-wrap: nowrap;\r\n  padding-left: 0;\r\n  min-width: 0;\r\n}\r\n\r\n/* Task Avatar */\r\n.tf-task-avatar {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 28px;\r\n  height: 28px;\r\n  border-radius: var(--tf-radius-pill);\r\n  border: 2px solid #ffffff;\r\n  background: linear-gradient(135deg, var(--tf-teal-light) 0%, #d1fae5 100%);\r\n  color: var(--tf-teal-base);\r\n  font-size: 0.65rem;\r\n  font-weight: 800;\r\n  letter-spacing: 0.02em;\r\n  box-shadow: var(--tf-shadow-sm);\r\n  flex-shrink: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.tf-task-avatar img {\r\n  width: 100%;\r\n  height: 100%;\r\n  display: block;\r\n  border-radius: var(--tf-radius-pill);\r\n  object-fit: cover;\r\n}\r\n\r\n/* Overlapping Avatar Effect */\r\n.tf-task-avatar + .tf-task-avatar {\r\n  margin-left: -10px;\r\n}\r\n\r\n.tf-task-avatar:nth-child(1) {\r\n  z-index: 3;\r\n}\r\n\r\n.tf-task-avatar:nth-child(2) {\r\n  z-index: 2;\r\n}\r\n\r\n.tf-task-avatar:nth-child(3) {\r\n  z-index: 1;\r\n}\r\n\r\n/* Unassigned */\r\n.tf-task-unassigned {\r\n  color: var(--tf-text-muted);\r\n  font-size: 0.75rem;\r\n  font-weight: 500;\r\n}\r\n\r\n/* Task Action Button */\r\n.tf-task-action {\r\n  width: fit-content;\r\n  padding: 6px 12px;\r\n  border: 1px solid #cbd5e1;\r\n  border-radius: var(--tf-radius-pill);\r\n  background: var(--tf-bg-card);\r\n  color: var(--tf-text-dark);\r\n  font-size: 0.7rem;\r\n  font-weight: 700;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.02em;\r\n  cursor: pointer;\r\n  transition: var(--tf-transition);\r\n  box-shadow: var(--tf-shadow-sm);\r\n  flex-shrink: 0;\r\n  white-space: nowrap;\r\n}\r\n\r\n.tf-task-action:hover:not(:disabled) {\r\n  background: #f1f5f9;\r\n  border-color: #94a3b8;\r\n}\r\n\r\n.tf-task-action--take {\r\n  color: var(--tf-teal-base);\r\n  border-color: var(--tf-teal-subtle);\r\n  background: var(--tf-teal-light);\r\n}\r\n\r\n.tf-task-action--take:hover:not(:disabled) {\r\n  background: var(--tf-teal-subtle);\r\n  border-color: var(--tf-teal-base);\r\n  color: var(--tf-teal-hover);\r\n}\r\n\r\n.tf-task-action--unassign {\r\n  border-color: #cbd5e1;\r\n  background: var(--tf-bg-card);\r\n  color: var(--tf-text-dark);\r\n}\r\n\r\n.tf-task-action--unassign:hover:not(:disabled) {\r\n  background: #f8fafc;\r\n  border-color: #94a3b8;\r\n}\r\n\r\n.tf-task-action:disabled {\r\n  opacity: 0.5;\r\n  cursor: not-allowed;\r\n}\r\n\r\n/* Task Helper Text */\r\n.tf-task-helper {\r\n  margin: 0;\r\n  color: var(--tf-text-light);\r\n  font-size: 0.7rem;\r\n  line-height: 1.3;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 1024px) {\r\n  .tf-board {\r\n    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\r\n    gap: 12px;\r\n    padding: 12px;\r\n  }\r\n}\r\n\r\n@media (max-width: 768px) {\r\n  .tf-board {\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .tf-column {\r\n    min-height: 300px;\r\n  }\r\n\r\n  .tf-task-footer-row {\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n  }\r\n\r\n  .tf-task-assignee-block {\r\n    width: 100%;\r\n  }\r\n\r\n  .tf-task-action {\r\n    width: 100%;\r\n    justify-content: center;\r\n  }\r\n}\r\n\r\n"],"sourceRoot":""}]);
