___CSS_LOADER_EXPORT___.push([module.id, `/* ── Metrics & Analytics Dashboard ─────────────────────────────── */

:root {
  --font-base: 'DM Sans', system-ui, sans-serif;
  --font-mono: 'DM Mono', monospace;

  --ink-900: #0b1622;
  --ink-700: #1e293b;
  --ink-500: #475569;
  --ink-300: #94a3b8;
  --ink-100: #e2e8f0;
  --ink-50:  #f8fafc;

  --brand:       #4f46e5;
  --brand-soft:  #eef2ff;
  --brand-muted: #c7d2fe;

  --green:       #10b981;
  --green-soft:  #ecfdf5;
  --amber:       #f59e0b;
  --amber-soft:  #fffbeb;
  --red:         #ef4444;
  --red-soft:    #fef2f2;

  --surface: #ffffff;
  --bg:      #f1f5f9;
  --border:  #e2e8f0;
  --shadow:  0 1px 3px rgba(15,23,42,.06), 0 4px 12px rgba(15,23,42,.04);
  --shadow-lg: 0 4px 24px rgba(15,23,42,.10);

  --radius:    14px;
  --radius-sm: 8px;
}

/* ── Page shell ─────────────────────────────────────────────────── */
.metrics-page {
  font-family: var(--font-base);
  color: var(--ink-700);
  width: min(1280px, 100%);
}

/* ── Header ─────────────────────────────────────────────────────── */
.metrics-header {
  padding: 0;
  max-width: none;
  margin: 0;
}

.metrics-title-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.metrics-title {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 800;
  color: var(--ink-900);
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.metrics-subtitle {
  margin: 3px 0 0;
  font-size: 0.85rem;
  color: var(--ink-300);
}

.metrics-project-name {
  margin: 4px 0 0;
  font-size: 1.65rem;
  font-weight: 700;
  color: var(--ink-900);
}

.metrics-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.metrics-refresh-btn {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink-700);
  padding: 7px 14px;
  font-family: var(--font-base);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: border-color .15s, background-color .15s, color .15s, opacity .15s;
}

.metrics-refresh-btn:hover:not(:disabled) {
  border-color: var(--brand-muted);
  background: var(--brand-soft);
  color: var(--brand);
}

.metrics-refresh-btn:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

.metrics-filter-label {
  font-size: 0.82rem;
  color: var(--ink-300);
}

.metrics-filter {
  font-family: var(--font-base);
  font-size: 0.84rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 7px 12px;
  background: var(--surface);
  color: var(--ink-700);
  cursor: pointer;
  outline: none;
  transition: border-color .15s;
}
.metrics-filter:focus { border-color: var(--brand); }

/* Insight banner */
.insight-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--brand-soft);
  border: 1px solid var(--brand-muted);
  border-radius: var(--radius-sm);
  padding: 11px 16px;
  color: var(--brand);
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 20px;
}
.insight-icon {
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ── Main content body ──────────────────────────────────────────── */
.metrics-body {
  max-width: none;
  margin: 0;
  padding: 0 0 56px;
  display: grid;
  gap: 18px;
}

/* ── KPI row ────────────────────────────────────────────────────── */
.kpi-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.kpi-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 20px 22px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: box-shadow .15s, transform .15s;
}
.kpi-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-1px);
}

/* keep legacy selectors working */
.kpi-card.kpi-elevated { background: var(--surface); }

.kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.kpi-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--ink-300);
}

.kpi-trend {
  font-size: 0.73rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 999px;
}

.badge-positive { background: var(--green-soft); color: var(--green); }
.badge-critical  { background: var(--red-soft);   color: var(--red);   }
.badge-neutral   { background: var(--brand-soft);  color: var(--brand); }

.kpi-value-large {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--ink-900);
  letter-spacing: -0.03em;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  margin-top: 6px;
}

.kpi-meta {
  font-size: 0.78rem;
  color: var(--ink-300);
  margin-top: 4px;
}

/* ── Generic panel shell ────────────────────────────────────────── */
.metrics-panel,
.metrics-card,
.review-panel {
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  padding: 22px;
  overflow: hidden;
  background-clip: padding-box;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}

.panel-title {
  margin: 0;
  font-size: 0.97rem;
  font-weight: 700;
  color: var(--ink-900);
}

.panel-sub {
  margin: 3px 0 0;
  font-size: 0.79rem;
  color: var(--ink-300);
}

/* ── Cycle time chart layout ────────────────────────────────────── */
.cycle-panel-body {
  display: grid;
  grid-template-columns: 1fr 130px;
  gap: 0;
  align-items: stretch;
}

.chart-area {
  min-width: 0;
  padding-right: 16px;
}

.chart-stat-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 18px;
  padding-left: 20px;
  border-left: 1px solid var(--border);
}

.stat-block { display: flex; flex-direction: column; gap: 2px; }

.stat-label {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-300);
}

.stat-value {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 500;
  color: var(--ink-900);
}

/* ── Two-col grid ───────────────────────────────────────────────── */
.metrics-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.metrics-card { padding: 22px; }

.metrics-card h3 {
  margin: 0 0 3px;
  font-size: 0.97rem;
  font-weight: 700;
  color: var(--ink-900);
}

.metrics-card-subtitle {
  font-size: 0.79rem;
  color: var(--ink-300);
  margin: 0 0 16px;
}

/* ── Horizontal bar chart ───────────────────────────────────────── */
.simple-bars {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 2px 0;
}

.simple-bar-item {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.simple-bar-row-top {
  display: grid;
  grid-template-columns: 36px 1fr auto;
  align-items: center;
  gap: 10px;
}

.simple-bar-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--brand-soft);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--brand);
  flex-shrink: 0;
  border: 1.5px solid var(--brand-muted);
}

.simple-bar-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--ink-700);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.simple-bar-val {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--ink-500);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.simple-bar-row-bottom {
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 10px;
}

.simple-bar-track {
  background: var(--ink-100);
  border-radius: 999px;
  height: 6px;
  overflow: hidden;
  grid-column: 2;
}

.simple-bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width .45s ease;
}

/* ── Donut chart ────────────────────────────────────────────────── */
.donut-wrap {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 24px;
  padding: 4px 0;
}

.donut-total-label {
  font-family: var(--font-base);
  font-size: 11px;
  font-weight: 700;
  fill: var(--ink-300);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.donut-total-value {
  font-family: var(--font-base);
  font-size: 26px;
  font-weight: 800;
  fill: var(--ink-900);
}

.donut-legend {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.donut-legend-row {
  display: grid;
  grid-template-columns: 8px 1fr auto auto;
  align-items: center;
  gap: 8px;
  font-size: 0.84rem;
}

.donut-swatch {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  flex-shrink: 0;
}

.donut-name { color: var(--ink-500); font-weight: 500; }
.donut-val  { color: var(--ink-900); font-weight: 700; font-variant-numeric: tabular-nums; }
.donut-pct  { color: var(--ink-300); font-size: 0.77rem; font-weight: 500; min-width: 34px; text-align: right; }

/* ── Review panel ───────────────────────────────────────────────── */
.review-panel { padding: 22px; }

.btn-tertiary {
  font-family: var(--font-base);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--brand);
  background: var(--brand-soft);
  border: 1px solid var(--brand-muted);
  border-radius: var(--radius-sm);
  padding: 6px 14px;
  cursor: pointer;
  transition: background .15s;
}
.btn-tertiary:hover { background: var(--brand-muted); }

.review-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.review-card {
  border-radius: var(--radius-sm);
  padding: 16px;
  border: 1px solid var(--border);
  border-left: 4px solid transparent;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: box-shadow .15s, transform .15s;
  background: var(--surface);
}
.review-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-1px);
}

.review-card-approved { border-left-color: var(--green); background: var(--green-soft); border-color: #bbf7d0; }
.review-card-rejected { border-left-color: var(--red);   background: var(--red-soft);   border-color: #fecaca; }
.review-card-pending  { border-left-color: var(--amber); background: var(--amber-soft); border-color: #fde68a; }

.review-card-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.avatar-sm {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--ink-100);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.78rem;
  color: var(--ink-700);
  flex-shrink: 0;
}

.reviewer-name {
  font-weight: 700;
  color: var(--ink-900);
  font-size: 0.88rem;
}

.review-time {
  font-size: 0.77rem;
  color: var(--ink-300);
  margin-top: 2px;
}

.review-badge {
  margin-left: auto;
  padding: 3px 9px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.67rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  flex-shrink: 0;
}
.badge-approved { background: #dcfce7; color: #15803d; }
.badge-rejected  { background: #fee2e2; color: #991b1b; }
.badge-pending   { background: #fef3c7; color: #92400e; }

.review-comment {
  font-size: 0.85rem;
  color: var(--ink-500);
  line-height: 1.5;
}

/* ── Empty states ───────────────────────────────────────────────── */
.empty-state,
.chart-empty {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-300);
  font-size: 0.875rem;
  padding: 24px 16px;
}

/* ── Responsive ─────────────────────────────────────────────────── */
@media (max-width: 1024px) {
  .kpi-row { grid-template-columns: 1fr 1fr; }
  .metrics-grid { grid-template-columns: 1fr; }
  .review-cards { grid-template-columns: 1fr 1fr; }
  .cycle-panel-body { grid-template-columns: 1fr; }
  .chart-stat-col {
    flex-direction: row;
    border-left: none;
    border-top: 1px solid var(--border);
    padding-left: 0;
    padding-top: 14px;
    margin-top: 8px;
    gap: 28px;
  }
}

@media (max-width: 768px) {
  .metrics-header { padding: 20px 16px 0; }
  .metrics-body   { padding: 0 16px 40px; }
  .metrics-title-row { flex-direction: column; align-items: flex-start; }
  .kpi-row { grid-template-columns: 1fr; }
  .review-cards { grid-template-columns: 1fr; }
  .donut-wrap { grid-template-columns: 1fr; justify-items: center; }
}`, "",{"version":3,"sources":["webpack://./src/components/styles/Metrics.css"],"names":[],"mappings":"AAAA,qEAAqE;;AAGrE;EACE,6CAA6C;EAC7C,iCAAiC;;EAEjC,kBAAkB;EAClB,kBAAkB;EAClB,kBAAkB;EAClB,kBAAkB;EAClB,kBAAkB;EAClB,kBAAkB;;EAElB,sBAAsB;EACtB,sBAAsB;EACtB,sBAAsB;;EAEtB,sBAAsB;EACtB,sBAAsB;EACtB,sBAAsB;EACtB,sBAAsB;EACtB,sBAAsB;EACtB,sBAAsB;;EAEtB,kBAAkB;EAClB,kBAAkB;EAClB,kBAAkB;EAClB,sEAAsE;EACtE,0CAA0C;;EAE1C,iBAAiB;EACjB,gBAAgB;AAClB;;AAEA,sEAAsE;AACtE;EACE,6BAA6B;EAC7B,qBAAqB;EACrB,wBAAwB;AAC1B;;AAEA,sEAAsE;AACtE;EACE,UAAU;EACV,eAAe;EACf,SAAS;AACX;;AAEA;EACE,aAAa;EACb,qBAAqB;EACrB,8BAA8B;EAC9B,SAAS;EACT,mBAAmB;AACrB;;AAEA;EACE,SAAS;EACT,iBAAiB;EACjB,gBAAgB;EAChB,qBAAqB;EACrB,wBAAwB;EACxB,gBAAgB;AAClB;;AAEA;EACE,eAAe;EACf,kBAAkB;EAClB,qBAAqB;AACvB;;AAEA;EACE,eAAe;EACf,kBAAkB;EAClB,gBAAgB;EAChB,qBAAqB;AACvB;;AAEA;EACE,aAAa;EACb,mBAAmB;EACnB,SAAS;AACX;;AAEA;EACE,+BAA+B;EAC/B,+BAA+B;EAC/B,0BAA0B;EAC1B,qBAAqB;EACrB,iBAAiB;EACjB,6BAA6B;EAC7B,kBAAkB;EAClB,gBAAgB;EAChB,eAAe;EACf,8EAA8E;AAChF;;AAEA;EACE,gCAAgC;EAChC,6BAA6B;EAC7B,mBAAmB;AACrB;;AAEA;EACE,aAAa;EACb,mBAAmB;AACrB;;AAEA;EACE,kBAAkB;EAClB,qBAAqB;AACvB;;AAEA;EACE,6BAA6B;EAC7B,kBAAkB;EAClB,+BAA+B;EAC/B,+BAA+B;EAC/B,iBAAiB;EACjB,0BAA0B;EAC1B,qBAAqB;EACrB,eAAe;EACf,aAAa;EACb,6BAA6B;AAC/B;AACA,wBAAwB,0BAA0B,EAAE;;AAEpD,mBAAmB;AACnB;EACE,aAAa;EACb,mBAAmB;EACnB,SAAS;EACT,6BAA6B;EAC7B,oCAAoC;EACpC,+BAA+B;EAC/B,kBAAkB;EAClB,mBAAmB;EACnB,mBAAmB;EACnB,gBAAgB;EAChB,mBAAmB;AACrB;AACA;EACE,cAAc;EACd,WAAW;EACX,YAAY;EACZ,aAAa;EACb,mBAAmB;EACnB,uBAAuB;AACzB;;AAEA,sEAAsE;AACtE;EACE,eAAe;EACf,SAAS;EACT,iBAAiB;EACjB,aAAa;EACb,SAAS;AACX;;AAEA,sEAAsE;AACtE;EACE,aAAa;EACb,qCAAqC;EACrC,SAAS;AACX;;AAEA;EACE,0BAA0B;EAC1B,4BAA4B;EAC5B,kBAAkB;EAClB,+BAA+B;EAC/B,yBAAyB;EACzB,aAAa;EACb,sBAAsB;EACtB,QAAQ;EACR,2CAA2C;AAC7C;AACA;EACE,4BAA4B;EAC5B,2BAA2B;AAC7B;;AAEA,kCAAkC;AAClC,yBAAyB,0BAA0B,EAAE;;AAErD;EACE,aAAa;EACb,mBAAmB;EACnB,8BAA8B;AAChC;;AAEA;EACE,kBAAkB;EAClB,gBAAgB;EAChB,yBAAyB;EACzB,sBAAsB;EACtB,qBAAqB;AACvB;;AAEA;EACE,kBAAkB;EAClB,gBAAgB;EAChB,gBAAgB;EAChB,oBAAoB;AACtB;;AAEA,kBAAkB,6BAA6B,EAAE,mBAAmB,EAAE;AACtE,mBAAmB,2BAA2B,IAAI,iBAAiB,IAAI;AACvE,mBAAmB,6BAA6B,GAAG,mBAAmB,EAAE;;AAExE;EACE,iBAAiB;EACjB,gBAAgB;EAChB,qBAAqB;EACrB,uBAAuB;EACvB,gBAAgB;EAChB,kCAAkC;EAClC,eAAe;AACjB;;AAEA;EACE,kBAAkB;EAClB,qBAAqB;EACrB,eAAe;AACjB;;AAEA,sEAAsE;AACtE;;;EAGE,0BAA0B;EAC1B,4BAA4B;EAC5B,+BAA+B;EAC/B,yBAAyB;EACzB,aAAa;EACb,gBAAgB;EAChB,4BAA4B;AAC9B;;AAEA;EACE,aAAa;EACb,8BAA8B;EAC9B,uBAAuB;EACvB,mBAAmB;AACrB;;AAEA;EACE,SAAS;EACT,kBAAkB;EAClB,gBAAgB;EAChB,qBAAqB;AACvB;;AAEA;EACE,eAAe;EACf,kBAAkB;EAClB,qBAAqB;AACvB;;AAEA,sEAAsE;AACtE;EACE,aAAa;EACb,gCAAgC;EAChC,MAAM;EACN,oBAAoB;AACtB;;AAEA;EACE,YAAY;EACZ,mBAAmB;AACrB;;AAEA;EACE,aAAa;EACb,sBAAsB;EACtB,uBAAuB;EACvB,uBAAuB;EACvB,SAAS;EACT,kBAAkB;EAClB,oCAAoC;AACtC;;AAEA,cAAc,aAAa,EAAE,sBAAsB,EAAE,QAAQ,EAAE;;AAE/D;EACE,kBAAkB;EAClB,gBAAgB;EAChB,yBAAyB;EACzB,sBAAsB;EACtB,qBAAqB;AACvB;;AAEA;EACE,6BAA6B;EAC7B,kBAAkB;EAClB,gBAAgB;EAChB,qBAAqB;AACvB;;AAEA,sEAAsE;AACtE;EACE,aAAa;EACb,8BAA8B;EAC9B,SAAS;AACX;;AAEA,gBAAgB,aAAa,EAAE;;AAE/B;EACE,eAAe;EACf,kBAAkB;EAClB,gBAAgB;EAChB,qBAAqB;AACvB;;AAEA;EACE,kBAAkB;EAClB,qBAAqB;EACrB,gBAAgB;AAClB;;AAEA,sEAAsE;AACtE;EACE,aAAa;EACb,sBAAsB;EACtB,SAAS;EACT,cAAc;AAChB;;AAEA;EACE,aAAa;EACb,sBAAsB;EACtB,QAAQ;AACV;;AAEA;EACE,aAAa;EACb,oCAAoC;EACpC,mBAAmB;EACnB,SAAS;AACX;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,6BAA6B;EAC7B,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,gBAAgB;EAChB,kBAAkB;EAClB,mBAAmB;EACnB,cAAc;EACd,sCAAsC;AACxC;;AAEA;EACE,mBAAmB;EACnB,gBAAgB;EAChB,qBAAqB;EACrB,mBAAmB;EACnB,gBAAgB;EAChB,uBAAuB;AACzB;;AAEA;EACE,kBAAkB;EAClB,gBAAgB;EAChB,qBAAqB;EACrB,mBAAmB;EACnB,kCAAkC;AACpC;;AAEA;EACE,aAAa;EACb,+BAA+B;EAC/B,SAAS;AACX;;AAEA;EACE,0BAA0B;EAC1B,oBAAoB;EACpB,WAAW;EACX,gBAAgB;EAChB,cAAc;AAChB;;AAEA;EACE,YAAY;EACZ,oBAAoB;EACpB,2BAA2B;AAC7B;;AAEA,sEAAsE;AACtE;EACE,aAAa;EACb,+BAA+B;EAC/B,mBAAmB;EACnB,SAAS;EACT,cAAc;AAChB;;AAEA;EACE,6BAA6B;EAC7B,eAAe;EACf,gBAAgB;EAChB,oBAAoB;EACpB,sBAAsB;EACtB,yBAAyB;AAC3B;;AAEA;EACE,6BAA6B;EAC7B,eAAe;EACf,gBAAgB;EAChB,oBAAoB;AACtB;;AAEA;EACE,aAAa;EACb,sBAAsB;EACtB,SAAS;AACX;;AAEA;EACE,aAAa;EACb,wCAAwC;EACxC,mBAAmB;EACnB,QAAQ;EACR,kBAAkB;AACpB;;AAEA;EACE,UAAU;EACV,WAAW;EACX,kBAAkB;EAClB,cAAc;AAChB;;AAEA,cAAc,qBAAqB,EAAE,gBAAgB,EAAE;AACvD,cAAc,qBAAqB,EAAE,gBAAgB,EAAE,kCAAkC,EAAE;AAC3F,cAAc,qBAAqB,EAAE,kBAAkB,EAAE,gBAAgB,EAAE,eAAe,EAAE,iBAAiB,EAAE;;AAE/G,sEAAsE;AACtE,gBAAgB,aAAa,EAAE;;AAE/B;EACE,6BAA6B;EAC7B,kBAAkB;EAClB,gBAAgB;EAChB,mBAAmB;EACnB,6BAA6B;EAC7B,oCAAoC;EACpC,+BAA+B;EAC/B,iBAAiB;EACjB,eAAe;EACf,2BAA2B;AAC7B;AACA,sBAAsB,8BAA8B,EAAE;;AAEtD;EACE,aAAa;EACb,qCAAqC;EACrC,SAAS;AACX;;AAEA;EACE,+BAA+B;EAC/B,aAAa;EACb,+BAA+B;EAC/B,kCAAkC;EAClC,aAAa;EACb,sBAAsB;EACtB,SAAS;EACT,2CAA2C;EAC3C,0BAA0B;AAC5B;AACA;EACE,4BAA4B;EAC5B,2BAA2B;AAC7B;;AAEA,wBAAwB,+BAA+B,EAAE,6BAA6B,EAAE,qBAAqB,EAAE;AAC/G,wBAAwB,6BAA6B,IAAI,2BAA2B,IAAI,qBAAqB,EAAE;AAC/G,wBAAwB,+BAA+B,EAAE,6BAA6B,EAAE,qBAAqB,EAAE;;AAE/G;EACE,aAAa;EACb,uBAAuB;EACvB,SAAS;AACX;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,0BAA0B;EAC1B,oBAAoB;EACpB,mBAAmB;EACnB,uBAAuB;EACvB,gBAAgB;EAChB,kBAAkB;EAClB,qBAAqB;EACrB,cAAc;AAChB;;AAEA;EACE,gBAAgB;EAChB,qBAAqB;EACrB,kBAAkB;AACpB;;AAEA;EACE,kBAAkB;EAClB,qBAAqB;EACrB,eAAe;AACjB;;AAEA;EACE,iBAAiB;EACjB,gBAAgB;EAChB,oBAAoB;EACpB,gBAAgB;EAChB,kBAAkB;EAClB,yBAAyB;EACzB,sBAAsB;EACtB,cAAc;AAChB;AACA,kBAAkB,mBAAmB,EAAE,cAAc,EAAE;AACvD,mBAAmB,mBAAmB,EAAE,cAAc,EAAE;AACxD,mBAAmB,mBAAmB,EAAE,cAAc,EAAE;;AAExD;EACE,kBAAkB;EAClB,qBAAqB;EACrB,gBAAgB;AAClB;;AAEA,sEAAsE;AACtE;;EAEE,aAAa;EACb,mBAAmB;EACnB,SAAS;EACT,qBAAqB;EACrB,mBAAmB;EACnB,kBAAkB;AACpB;;AAEA,sEAAsE;AACtE;EACE,WAAW,8BAA8B,EAAE;EAC3C,gBAAgB,0BAA0B,EAAE;EAC5C,gBAAgB,8BAA8B,EAAE;EAChD,oBAAoB,0BAA0B,EAAE;EAChD;IACE,mBAAmB;IACnB,iBAAiB;IACjB,mCAAmC;IACnC,eAAe;IACf,iBAAiB;IACjB,eAAe;IACf,SAAS;EACX;AACF;;AAEA;EACE,kBAAkB,oBAAoB,EAAE;EACxC,kBAAkB,oBAAoB,EAAE;EACxC,qBAAqB,sBAAsB,EAAE,uBAAuB,EAAE;EACtE,WAAW,0BAA0B,EAAE;EACvC,gBAAgB,0BAA0B,EAAE;EAC5C,cAAc,0BAA0B,EAAE,qBAAqB,EAAE;AACnE","sourcesContent":["/* ── Metrics & Analytics Dashboard ─────────────────────────────── */\r\n@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap');\r\n\r\n:root {\r\n  --font-base: 'DM Sans', system-ui, sans-serif;\r\n  --font-mono: 'DM Mono', monospace;\r\n\r\n  --ink-900: #0b1622;\r\n  --ink-700: #1e293b;\r\n  --ink-500: #475569;\r\n  --ink-300: #94a3b8;\r\n  --ink-100: #e2e8f0;\r\n  --ink-50:  #f8fafc;\r\n\r\n  --brand:       #4f46e5;\r\n  --brand-soft:  #eef2ff;\r\n  --brand-muted: #c7d2fe;\r\n\r\n  --green:       #10b981;\r\n  --green-soft:  #ecfdf5;\r\n  --amber:       #f59e0b;\r\n  --amber-soft:  #fffbeb;\r\n  --red:         #ef4444;\r\n  --red-soft:    #fef2f2;\r\n\r\n  --surface: #ffffff;\r\n  --bg:      #f1f5f9;\r\n  --border:  #e2e8f0;\r\n  --shadow:  0 1px 3px rgba(15,23,42,.06), 0 4px 12px rgba(15,23,42,.04);\r\n  --shadow-lg: 0 4px 24px rgba(15,23,42,.10);\r\n\r\n  --radius:    14px;\r\n  --radius-sm: 8px;\r\n}\r\n\r\n/* ── Page shell ─────────────────────────────────────────────────── */\r\n.metrics-page {\r\n  font-family: var(--font-base);\r\n  color: var(--ink-700);\r\n  width: min(1280px, 100%);\r\n}\r\n\r\n/* ── Header ─────────────────────────────────────────────────────── */\r\n.metrics-header {\r\n  padding: 0;\r\n  max-width: none;\r\n  margin: 0;\r\n}\r\n\r\n.metrics-title-row {\r\n  display: flex;\r\n  align-items: flex-end;\r\n  justify-content: space-between;\r\n  gap: 16px;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.metrics-title {\r\n  margin: 0;\r\n  font-size: 0.9rem;\r\n  font-weight: 800;\r\n  color: var(--ink-900);\r\n  letter-spacing: -0.025em;\r\n  line-height: 1.2;\r\n}\r\n\r\n.metrics-subtitle {\r\n  margin: 3px 0 0;\r\n  font-size: 0.85rem;\r\n  color: var(--ink-300);\r\n}\r\n\r\n.metrics-project-name {\r\n  margin: 4px 0 0;\r\n  font-size: 1.65rem;\r\n  font-weight: 700;\r\n  color: var(--ink-900);\r\n}\r\n\r\n.metrics-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n.metrics-refresh-btn {\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-sm);\r\n  background: var(--surface);\r\n  color: var(--ink-700);\r\n  padding: 7px 14px;\r\n  font-family: var(--font-base);\r\n  font-size: 0.84rem;\r\n  font-weight: 700;\r\n  cursor: pointer;\r\n  transition: border-color .15s, background-color .15s, color .15s, opacity .15s;\r\n}\r\n\r\n.metrics-refresh-btn:hover:not(:disabled) {\r\n  border-color: var(--brand-muted);\r\n  background: var(--brand-soft);\r\n  color: var(--brand);\r\n}\r\n\r\n.metrics-refresh-btn:disabled {\r\n  opacity: 0.65;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.metrics-filter-label {\r\n  font-size: 0.82rem;\r\n  color: var(--ink-300);\r\n}\r\n\r\n.metrics-filter {\r\n  font-family: var(--font-base);\r\n  font-size: 0.84rem;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-sm);\r\n  padding: 7px 12px;\r\n  background: var(--surface);\r\n  color: var(--ink-700);\r\n  cursor: pointer;\r\n  outline: none;\r\n  transition: border-color .15s;\r\n}\r\n.metrics-filter:focus { border-color: var(--brand); }\r\n\r\n/* Insight banner */\r\n.insight-banner {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  background: var(--brand-soft);\r\n  border: 1px solid var(--brand-muted);\r\n  border-radius: var(--radius-sm);\r\n  padding: 11px 16px;\r\n  color: var(--brand);\r\n  font-size: 0.875rem;\r\n  font-weight: 500;\r\n  margin-bottom: 20px;\r\n}\r\n.insight-icon {\r\n  flex-shrink: 0;\r\n  width: 26px;\r\n  height: 26px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n/* ── Main content body ──────────────────────────────────────────── */\r\n.metrics-body {\r\n  max-width: none;\r\n  margin: 0;\r\n  padding: 0 0 56px;\r\n  display: grid;\r\n  gap: 18px;\r\n}\r\n\r\n/* ── KPI row ────────────────────────────────────────────────────── */\r\n.kpi-row {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 14px;\r\n}\r\n\r\n.kpi-card {\r\n  background: var(--surface);\r\n  border-radius: var(--radius);\r\n  padding: 20px 22px;\r\n  border: 1px solid var(--border);\r\n  box-shadow: var(--shadow);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 4px;\r\n  transition: box-shadow .15s, transform .15s;\r\n}\r\n.kpi-card:hover {\r\n  box-shadow: var(--shadow-lg);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* keep legacy selectors working */\r\n.kpi-card.kpi-elevated { background: var(--surface); }\r\n\r\n.kpi-top {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n.kpi-title {\r\n  font-size: 0.75rem;\r\n  font-weight: 700;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.07em;\r\n  color: var(--ink-300);\r\n}\r\n\r\n.kpi-trend {\r\n  font-size: 0.73rem;\r\n  font-weight: 700;\r\n  padding: 3px 9px;\r\n  border-radius: 999px;\r\n}\r\n\r\n.badge-positive { background: var(--green-soft); color: var(--green); }\r\n.badge-critical  { background: var(--red-soft);   color: var(--red);   }\r\n.badge-neutral   { background: var(--brand-soft);  color: var(--brand); }\r\n\r\n.kpi-value-large {\r\n  font-size: 2.2rem;\r\n  font-weight: 800;\r\n  color: var(--ink-900);\r\n  letter-spacing: -0.03em;\r\n  line-height: 1.1;\r\n  font-variant-numeric: tabular-nums;\r\n  margin-top: 6px;\r\n}\r\n\r\n.kpi-meta {\r\n  font-size: 0.78rem;\r\n  color: var(--ink-300);\r\n  margin-top: 4px;\r\n}\r\n\r\n/* ── Generic panel shell ────────────────────────────────────────── */\r\n.metrics-panel,\r\n.metrics-card,\r\n.review-panel {\r\n  background: var(--surface);\r\n  border-radius: var(--radius);\r\n  border: 1px solid var(--border);\r\n  box-shadow: var(--shadow);\r\n  padding: 22px;\r\n  overflow: hidden;\r\n  background-clip: padding-box;\r\n}\r\n\r\n.panel-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  margin-bottom: 16px;\r\n}\r\n\r\n.panel-title {\r\n  margin: 0;\r\n  font-size: 0.97rem;\r\n  font-weight: 700;\r\n  color: var(--ink-900);\r\n}\r\n\r\n.panel-sub {\r\n  margin: 3px 0 0;\r\n  font-size: 0.79rem;\r\n  color: var(--ink-300);\r\n}\r\n\r\n/* ── Cycle time chart layout ────────────────────────────────────── */\r\n.cycle-panel-body {\r\n  display: grid;\r\n  grid-template-columns: 1fr 130px;\r\n  gap: 0;\r\n  align-items: stretch;\r\n}\r\n\r\n.chart-area {\r\n  min-width: 0;\r\n  padding-right: 16px;\r\n}\r\n\r\n.chart-stat-col {\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  align-items: flex-start;\r\n  gap: 18px;\r\n  padding-left: 20px;\r\n  border-left: 1px solid var(--border);\r\n}\r\n\r\n.stat-block { display: flex; flex-direction: column; gap: 2px; }\r\n\r\n.stat-label {\r\n  font-size: 0.72rem;\r\n  font-weight: 700;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.06em;\r\n  color: var(--ink-300);\r\n}\r\n\r\n.stat-value {\r\n  font-family: var(--font-mono);\r\n  font-size: 1.35rem;\r\n  font-weight: 500;\r\n  color: var(--ink-900);\r\n}\r\n\r\n/* ── Two-col grid ───────────────────────────────────────────────── */\r\n.metrics-grid {\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 16px;\r\n}\r\n\r\n.metrics-card { padding: 22px; }\r\n\r\n.metrics-card h3 {\r\n  margin: 0 0 3px;\r\n  font-size: 0.97rem;\r\n  font-weight: 700;\r\n  color: var(--ink-900);\r\n}\r\n\r\n.metrics-card-subtitle {\r\n  font-size: 0.79rem;\r\n  color: var(--ink-300);\r\n  margin: 0 0 16px;\r\n}\r\n\r\n/* ── Horizontal bar chart ───────────────────────────────────────── */\r\n.simple-bars {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n  padding: 2px 0;\r\n}\r\n\r\n.simple-bar-item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 7px;\r\n}\r\n\r\n.simple-bar-row-top {\r\n  display: grid;\r\n  grid-template-columns: 36px 1fr auto;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n.simple-bar-avatar {\r\n  width: 36px;\r\n  height: 36px;\r\n  border-radius: 50%;\r\n  background: var(--brand-soft);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-weight: 700;\r\n  font-size: 0.75rem;\r\n  color: var(--brand);\r\n  flex-shrink: 0;\r\n  border: 1.5px solid var(--brand-muted);\r\n}\r\n\r\n.simple-bar-label {\r\n  font-size: 0.875rem;\r\n  font-weight: 500;\r\n  color: var(--ink-700);\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.simple-bar-val {\r\n  font-size: 0.82rem;\r\n  font-weight: 700;\r\n  color: var(--ink-500);\r\n  white-space: nowrap;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.simple-bar-row-bottom {\r\n  display: grid;\r\n  grid-template-columns: 36px 1fr;\r\n  gap: 10px;\r\n}\r\n\r\n.simple-bar-track {\r\n  background: var(--ink-100);\r\n  border-radius: 999px;\r\n  height: 6px;\r\n  overflow: hidden;\r\n  grid-column: 2;\r\n}\r\n\r\n.simple-bar-fill {\r\n  height: 100%;\r\n  border-radius: 999px;\r\n  transition: width .45s ease;\r\n}\r\n\r\n/* ── Donut chart ────────────────────────────────────────────────── */\r\n.donut-wrap {\r\n  display: grid;\r\n  grid-template-columns: auto 1fr;\r\n  align-items: center;\r\n  gap: 24px;\r\n  padding: 4px 0;\r\n}\r\n\r\n.donut-total-label {\r\n  font-family: var(--font-base);\r\n  font-size: 11px;\r\n  font-weight: 700;\r\n  fill: var(--ink-300);\r\n  letter-spacing: 0.05em;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.donut-total-value {\r\n  font-family: var(--font-base);\r\n  font-size: 26px;\r\n  font-weight: 800;\r\n  fill: var(--ink-900);\r\n}\r\n\r\n.donut-legend {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n}\r\n\r\n.donut-legend-row {\r\n  display: grid;\r\n  grid-template-columns: 8px 1fr auto auto;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-size: 0.84rem;\r\n}\r\n\r\n.donut-swatch {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 2px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.donut-name { color: var(--ink-500); font-weight: 500; }\r\n.donut-val  { color: var(--ink-900); font-weight: 700; font-variant-numeric: tabular-nums; }\r\n.donut-pct  { color: var(--ink-300); font-size: 0.77rem; font-weight: 500; min-width: 34px; text-align: right; }\r\n\r\n/* ── Review panel ───────────────────────────────────────────────── */\r\n.review-panel { padding: 22px; }\r\n\r\n.btn-tertiary {\r\n  font-family: var(--font-base);\r\n  font-size: 0.82rem;\r\n  font-weight: 600;\r\n  color: var(--brand);\r\n  background: var(--brand-soft);\r\n  border: 1px solid var(--brand-muted);\r\n  border-radius: var(--radius-sm);\r\n  padding: 6px 14px;\r\n  cursor: pointer;\r\n  transition: background .15s;\r\n}\r\n.btn-tertiary:hover { background: var(--brand-muted); }\r\n\r\n.review-cards {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 14px;\r\n}\r\n\r\n.review-card {\r\n  border-radius: var(--radius-sm);\r\n  padding: 16px;\r\n  border: 1px solid var(--border);\r\n  border-left: 4px solid transparent;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n  transition: box-shadow .15s, transform .15s;\r\n  background: var(--surface);\r\n}\r\n.review-card:hover {\r\n  box-shadow: var(--shadow-lg);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n.review-card-approved { border-left-color: var(--green); background: var(--green-soft); border-color: #bbf7d0; }\r\n.review-card-rejected { border-left-color: var(--red);   background: var(--red-soft);   border-color: #fecaca; }\r\n.review-card-pending  { border-left-color: var(--amber); background: var(--amber-soft); border-color: #fde68a; }\r\n\r\n.review-card-top {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 10px;\r\n}\r\n\r\n.avatar-sm {\r\n  width: 36px;\r\n  height: 36px;\r\n  border-radius: 50%;\r\n  background: var(--ink-100);\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-weight: 700;\r\n  font-size: 0.78rem;\r\n  color: var(--ink-700);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.reviewer-name {\r\n  font-weight: 700;\r\n  color: var(--ink-900);\r\n  font-size: 0.88rem;\r\n}\r\n\r\n.review-time {\r\n  font-size: 0.77rem;\r\n  color: var(--ink-300);\r\n  margin-top: 2px;\r\n}\r\n\r\n.review-badge {\r\n  margin-left: auto;\r\n  padding: 3px 9px;\r\n  border-radius: 999px;\r\n  font-weight: 700;\r\n  font-size: 0.67rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.06em;\r\n  flex-shrink: 0;\r\n}\r\n.badge-approved { background: #dcfce7; color: #15803d; }\r\n.badge-rejected  { background: #fee2e2; color: #991b1b; }\r\n.badge-pending   { background: #fef3c7; color: #92400e; }\r\n\r\n.review-comment {\r\n  font-size: 0.85rem;\r\n  color: var(--ink-500);\r\n  line-height: 1.5;\r\n}\r\n\r\n/* ── Empty states ───────────────────────────────────────────────── */\r\n.empty-state,\r\n.chart-empty {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  color: var(--ink-300);\r\n  font-size: 0.875rem;\r\n  padding: 24px 16px;\r\n}\r\n\r\n/* ── Responsive ─────────────────────────────────────────────────── */\r\n@media (max-width: 1024px) {\r\n  .kpi-row { grid-template-columns: 1fr 1fr; }\r\n  .metrics-grid { grid-template-columns: 1fr; }\r\n  .review-cards { grid-template-columns: 1fr 1fr; }\r\n  .cycle-panel-body { grid-template-columns: 1fr; }\r\n  .chart-stat-col {\r\n    flex-direction: row;\r\n    border-left: none;\r\n    border-top: 1px solid var(--border);\r\n    padding-left: 0;\r\n    padding-top: 14px;\r\n    margin-top: 8px;\r\n    gap: 28px;\r\n  }\r\n}\r\n\r\n@media (max-width: 768px) {\r\n  .metrics-header { padding: 20px 16px 0; }\r\n  .metrics-body   { padding: 0 16px 40px; }\r\n  .metrics-title-row { flex-direction: column; align-items: flex-start; }\r\n  .kpi-row { grid-template-columns: 1fr; }\r\n  .review-cards { grid-template-columns: 1fr; }\r\n  .donut-wrap { grid-template-columns: 1fr; justify-items: center; }\r\n}"],"sourceRoot":""}]);
